const LOGO = "data:image/jpeg;base64,";
const PRODUCTS = [["Pink Lily Bloom", "Soft pink handmade bouquet", "Custom quote", "data:image/jpeg;base64,"], ["Pastel Garden", "Colourful bouquet with layered blooms", "Custom quote", "data:image/jpeg;base64,"], ["Blush Blossom", "Pink & rose handmade arrangement", "Custom quote", "data:image/jpeg;base64,"], ["Blue Daisy Bouquet", "Fresh blue floral arrangement", "Custom quote", "data:image/jpeg;base64,"], ["Floral Gift Bags", "Cute handmade flower gift bags", "Custom quote", "data:image/jpeg;base64,"], ["Soft Pink Pom", "Delicate round bloom bouquet", "Custom quote", "data:image/jpeg;base64,"], ["Red Hibiscus", "Statement handmade flower", "Custom quote", "data:image/jpeg;base64,"], ["Pink Petal Bouquet", "Classic soft-pink bouquet", "Custom quote", "data:image/jpeg;base64,"], ["Tulip Garden", "Pastel tulip-style handmade bouquet", "Custom quote", "data:image/jpeg;base64,"], ["Sunshine Bloom", "Bright mixed-flower bouquet", "Custom quote", "data:image/jpeg;base64,"], ["Teddy Bouquet", "Playful handmade gift bouquet", "Custom quote", "data:image/jpeg;base64,"]];

const app = document.getElementById("app");
const nav = document.getElementById("nav");
const menuBtn = document.getElementById("menuBtn");
const toast = document.getElementById("toast");

document.getElementById("brandLogo").src = LOGO;
document.getElementById("footerLogo").src = LOGO;

menuBtn.addEventListener("click",()=>nav.classList.toggle("open"));
document.addEventListener("click",e=>{ if(!e.target.closest(".site-header")) nav.classList.remove("open"); });

function productCard(p){
  return `<article class="product">
    <div class="product-img"><img src="${p[3]}" alt="${p[0]}" loading="lazy"></div>
    <div class="product-body">
      <h3>${p[0]}</h3>
      <p>${p[1]}</p>
      <div class="price">${p[2]}</div>
      <a class="card-btn" href="#order">Ask about this piece →</a>
    </div>
  </article>`;
}

function hero(){
 return `<section class="hero page">
   <div class="container hero-grid">
     <div>
       <div class="eyebrow">Little Art Studio • Pakistan</div>
       <h1>Handmade pieces<br>made with <em>heart.</em></h1>
       <p>Thoughtful bouquets and little handmade creations for birthdays, surprises, celebrations and the moments you want to make special.</p>
       <div class="actions"><a class="btn primary" href="#shop">Shop bouquets →</a><a class="btn secondary" href="#order">Custom order</a></div>
       <p style="font-size:12px;margin-top:16px">Custom & bulk orders • Delivery across Pakistan</p>
     </div>
     <div class="hero-art">
       <div class="float-flower">✿</div>
       <div class="hero-card"><img src="${PRODUCTS[1][3]}" alt="Handmade pink bouquet"></div>
       <div class="hero-badge"><strong>Made by hand</strong>Each piece is prepared with care.</div>
     </div>
   </div>
 </section>
 <section class="section">
   <div class="container">
     <div class="section-head"><div><div class="eyebrow">Made for gifting</div><h2>Little things,<br>big feelings.</h2></div><p>Choose a ready design or tell us your colour, flower style and occasion. We'll help you make it yours.</p></div>
     <div class="grid">${PRODUCTS.slice(0,6).map(productCard).join("")}</div>
   </div>
 </section>
 <section class="section soft"><div class="container"><div class="offer">
   <div><div class="eyebrow" style="color:#eadcf2">Special offer</div><h2>Free delivery on purchases of 2000/- and above.</h2><p>Perfect for surprise gifting. DM us to check current designs, colours and availability.</p><a class="btn" href="#order">Start an order →</a></div>
   <div style="font-size:110px;text-align:center;opacity:.25">✿</div>
 </div></div></section>`;
}

function shop(){
 return `<section class="section page"><div class="container">
   <div class="section-head"><div><div class="eyebrow">The bouquet shelf</div><h2>Handmade bouquets</h2></div><p>Colours can be customised. Message us for the latest designs and a final quote.</p></div>
   <div class="grid">${PRODUCTS.map(productCard).join("")}</div>
 </div></section>`;
}

function collections(){
 const sets=[["Soft & Pretty",PRODUCTS[1][3],"Pastel bouquets"],["Bright & Playful",PRODUCTS[10][3],"Colourful gifting"],["Classic Florals",PRODUCTS[3][3],"Timeless handmade blooms"]];
 return `<section class="section page"><div class="container">
   <div class="section-head"><div><div class="eyebrow">Find your vibe</div><h2>Collections</h2></div><p>From soft pastel surprises to colourful statement pieces, there is a little something for every kind of celebration.</p></div>
   <div class="collection-grid">${sets.map(s=>`<a class="collection" href="#shop"><img src="${s[1]}" alt="${s[0]}"><div class="label"><h3>${s[0]}</h3><span>${s[2]} →</span></div></a>`).join("")}</div>
 </div></section>`;
}

function about(){
 return `<section class="section page"><div class="container story">
   <div class="story-logo"><img src="${LOGO}" alt="Rustic Hands logo"></div>
   <div class="story-copy"><div class="eyebrow">About Rustic Hands</div><h2>A tiny studio for handmade happiness.</h2>
   <p>Rustic Hands is a Little Art Studio from Pakistan creating handmade bouquets and playful art pieces for gifting.</p>
   <p>Every order is made with attention to colour, details and the feeling behind the gift. Whether it's a small surprise or a bulk order, we love creating something that feels personal.</p>
   <div class="points">
     <div class="point"><b>🌸 Handmade</b>Created piece by piece.</div>
     <div class="point"><b>🎀 Custom</b>Colours and designs can be discussed.</div>
     <div class="point"><b>📦 Bulk orders</b>For events, gifting & special occasions.</div>
     <div class="point"><b>🚚 Pakistan delivery</b>Delivery available across Pakistan.</div>
   </div></div>
 </div></section>`;
}

function order(){
 return `<section class="section page"><div class="container order-wrap">
   <div class="order-info"><img src="${LOGO}" style="width:86px;height:86px;border-radius:50%;object-fit:cover;margin-bottom:20px" alt="Rustic Hands">
     <h2>Let's make your gift.</h2><p>Tell us what you have in mind and we'll get back to you with design options, availability and the final quote.</p>
     <div class="contact-line">📍 KHI • Pakistan</div><div class="contact-line">💌 DM for order</div><div class="contact-line">🚚 Delivery across Pakistan</div>
   </div>
   <form class="form" id="orderForm">
     <div class="eyebrow">Custom order enquiry</div><h2 style="font-size:32px;margin-bottom:20px">Tell us the details</h2>
     <div class="form-grid">
       <div class="field"><label>Your name</label><input required name="name" placeholder="Your name"></div>
       <div class="field"><label>Occasion</label><input name="occasion" placeholder="Birthday, anniversary..."></div>
       <div class="field"><label>Preferred colour</label><input name="colour" placeholder="Pink, purple, mixed..."></div>
       <div class="field"><label>Approx. budget</label><input name="budget" placeholder="Optional"></div>
       <div class="field full"><label>What would you like?</label><textarea required name="details" placeholder="Tell us about the bouquet / gift you want..."></textarea></div>
       <div class="field full"><button class="btn primary" type="submit">Send enquiry →</button></div>
     </div>
   </form>
 </div></section>`;
}

function notFound(){return `<section class="empty page"><div class="container"><h2>Something handmade is coming.</h2><p>Let's take you back to the studio.</p><a class="btn primary" href="#home">Back home</a></div></section>`}

function render(){
  const route=location.hash.replace("#","").split("?")[0]||"home";
  const pages={home:hero,shop,collections,about,order};
  app.innerHTML=(pages[route]||notFound)();
  nav.classList.remove("open");
  window.scrollTo({top:0,behavior:"smooth"});
  const form=document.getElementById("orderForm");
  if(form) form.addEventListener("submit",e=>{
    e.preventDefault();
    const name=new FormData(form).get("name");
    toast.textContent=`Thanks ${name}! Your enquiry is ready — please DM @rustic_hands65 to continue.`;
    toast.classList.add("show"); form.reset();
    setTimeout(()=>toast.classList.remove("show"),4500);
  });
}
window.addEventListener("hashchange",render);
render();
